MG.add({
  id: 'lexicon', name: 'Lexicon', cat: 'Puzzle', color: '#22c55e', color2: '#eab308', w: 600, h: 860, typing: true,
  desc: 'Guess the hidden five-letter word in six tries. Solve word after word to build a streak — one miss ends it.',
  how: ['Type a five-letter word and press <kbd>Enter</kbd> (or use the on-screen keys)', '<b style="color:#22c55e">Green</b> = right letter, right spot · <b style="color:#eab308">Yellow</b> = in the word, wrong spot', 'Grey letters are not in the word at all', 'Fewer guesses score more · keep your streak alive'],
  make(E) {
    const W = 600, H = 860;
    // Guess list: MIT-licensed `word-list` package (5-letter entries). Answers: hand-picked common words.
    const GUESS = '';
    const ANS = '';
    const valid = new Set(); for (let i = 0; i < GUESS.length; i += 5) valid.add(GUESS.slice(i, i + 5));
    const answers = []; for (let i = 0; i < ANS.length; i += 5) answers.push(ANS.slice(i, i + 5));
    const TS = 70, GAP = 9, GX = (W - (5 * TS + 4 * GAP)) / 2, GY = 96;
    const KEYS = ['qwertyuiop', 'asdfghjkl', '<zxcvbnm>'];
    const C = { g: '#16a34a', y: '#ca8a04', x: '#3f3f46', e: '#18181b' };
    let answer, rows, cur, kb, st, stT, streak = 0, shake = 0, toast = null, T = 0, used = new Set(), solvedCount = 0;
    function newWord() {
      let a; do a = U.pick(answers); while (used.has(a) && used.size < answers.length); used.add(a); answer = a;
      rows = U.range(6).map(() => ({ letters: '', res: null, flip: 0, bounce: 0 })); cur = 0; kb = {}; st = 'play';
      E.stat('Streak', streak);
    }
    newWord();
    function score(guess) {
      const res = Array(5).fill('x'), cnt = {};
      for (let i = 0; i < 5; i++) { if (guess[i] === answer[i]) res[i] = 'g'; else cnt[answer[i]] = (cnt[answer[i]] || 0) + 1; }
      for (let i = 0; i < 5; i++) if (res[i] !== 'g' && cnt[guess[i]]) { res[i] = 'y'; cnt[guess[i]]--; }
      return res;
    }
    function submit() {
      const r = rows[cur];
      if (r.letters.length < 5) { say('Not enough letters'); shake = 0.4; E.sfx('error', 1.2, 0.5); return; }
      if (!valid.has(r.letters)) { say('Not in word list'); shake = 0.4; E.sfx('error', 1.2, 0.5); return; }
      r.res = score(r.letters); r.flip = 0; st = 'reveal'; stT = 5 * 0.28 + 0.2;
      r.res.forEach((v, i) => E.after(i * 0.28 + 0.14, () => { E.sfx(v === 'g' ? 'ding' : v === 'y' ? 'select' : 'card', v === 'g' ? 1.4 : 1, 0.45); const k = r.letters[i]; const rank = { g: 3, y: 2, x: 1 }; if (!kb[k] || rank[v] > rank[kb[k]]) kb[k] = v; }));
    }
    function say(msg) { toast = { msg, t: 1.6 }; }
    function press(k) {
      if (st !== 'play') return;
      const r = rows[cur];
      if (k === 'Enter' || k === '>') submit();
      else if (k === 'Backspace' || k === '<') { r.letters = r.letters.slice(0, -1); E.sfx('tick', 0.8, 0.4); }
      else if (/^[a-z]$/i.test(k) && r.letters.length < 5) { r.letters += k.toLowerCase(); r.pop = 1; r.popI = r.letters.length - 1; E.sfx('tick', 1.3, 0.4); }
    }
    function afterReveal() {
      const r = rows[cur];
      if (r.res.every((v) => v === 'g')) {
        streak++; solvedCount++;
        const pts = (6 - cur) * 100 + streak * 50; E.score += pts;
        st = 'won'; stT = 2.6; r.bounce = 1;
        E.sfx('win'); say(['Genius!', 'Magnificent!', 'Impressive!', 'Splendid!', 'Great!', 'Phew!'][cur]);
        E.pop(W / 2, GY + cur * (TS + GAP) + TS / 2, `+${pts}`, { color: '#4ade80', size: 30 });
        E.burst(W / 2, GY + cur * (TS + GAP) + TS / 2, { n: 40, colors: ['#22c55e', '#eab308', '#fff'], speed: 320 });
        E.stat('Streak', streak);
      } else if (cur >= 5) {
        st = 'lost'; E.sfx('lose'); say(answer.toUpperCase());
        E.after(2.2, () => E.over({ title: 'Streak Over', msg: `The word was ${answer.toUpperCase()} · you solved ${solvedCount} word${solvedCount === 1 ? '' : 's'} in a row` }));
      } else { cur++; st = 'play'; }
    }
    const keyRects = [];
    KEYS.forEach((row, ri) => {
      const wide = 64, kw = 50, gap = 6, n = row.length;
      const total = [...row].reduce((s, ch) => s + (ch === '<' || ch === '>' ? wide : kw), 0) + gap * (n - 1);
      let x = (W - total) / 2;
      for (const ch of row) { const w = ch === '<' || ch === '>' ? wide : kw; keyRects.push({ ch, x, y: 640 + ri * 66, w, h: 58 }); x += w + gap; }
    });
    return {
      update(dt) {
        T += dt; shake = Math.max(0, shake - dt);
        if (toast) { toast.t -= dt; if (toast.t <= 0) toast = null; }
        for (const r of rows) { if (r.res && r.flip < 1) r.flip = Math.min(1, r.flip + dt / (5 * 0.28 + 0.14)); r.bounce = Math.max(0, r.bounce - dt * 0.8); if (r.pop) r.pop = Math.max(0, r.pop - dt * 8); }
        if (st === 'reveal') { stT -= dt; if (stT <= 0) afterReveal(); return; }
        if (st === 'won') { stT -= dt; if (stT <= 0) newWord(); return; }
        if (st !== 'play') return;
        for (const k of E.typed) press(k);
        if (E.ptr.hit) for (const k of keyRects) if (U.ptInRect(E.ptr.x, E.ptr.y, k.x, k.y, k.w, k.h)) { k.press = 0.12; press(k.ch); }
        for (const k of keyRects) if (k.press) k.press = Math.max(0, k.press - dt);
      },
      draw(g) {
        D.bg(g, W, H, '#0c0a09', '#1c1917');
        D.text(g, 'LEXICON', W / 2, 44, { size: 34, color: '#f5f5f4', glow: '#22c55e', blur: 10 });
        D.text(g, `streak ${streak}`, W / 2, 74, { size: 13, font: 'mono', color: 'rgba(255,255,255,.45)' });
        rows.forEach((r, ri) => {
          const sx = ri === cur && shake > 0 ? Math.sin(shake * 60) * 10 * shake : 0;
          for (let i = 0; i < 5; i++) {
            const x = GX + i * (TS + GAP) + sx, y = GY + ri * (TS + GAP);
            const ch = r.letters[i] || '';
            // flip timing per tile
            let f = 0; if (r.res) f = U.clamp((r.flip * (5 * 0.28 + 0.14) - i * 0.28) / 0.28, 0, 1);
            const showRes = r.res && f >= 0.5, sy = r.res ? Math.abs(Math.cos(f * Math.PI)) : 1;
            const bounce = r.bounce > 0 ? Math.max(0, Math.sin((1 - r.bounce) * 12 - i * 0.6)) * 14 * r.bounce : 0;
            const pop = r.pop && r.popI === i ? 1 + r.pop * 0.12 : 1;
            g.save(); g.translate(x + TS / 2, y + TS / 2 - bounce); g.scale(pop, sy * pop);
            if (showRes) { D.fillRR(g, -TS / 2, -TS / 2, TS, TS, 6, C[r.res[i]]); }
            else { D.fillRR(g, -TS / 2, -TS / 2, TS, TS, 6, C.e); D.strokeRR(g, -TS / 2, -TS / 2, TS, TS, 6, ch ? '#71717a' : '#3f3f46', 2); }
            if (ch) D.text(g, ch.toUpperCase(), 0, 2, { size: 36, color: '#fafafa' });
            g.restore();
          }
        });
        for (const k of keyRects) {
          const s = kb[k.ch], bg = s ? C[s] : '#57534e';
          D.fillRR(g, k.x, k.y + (k.press ? 2 : 0), k.w, k.h, 8, bg);
          D.text(g, k.ch === '<' ? '⌫' : k.ch === '>' ? 'ENTER' : k.ch.toUpperCase(), k.x + k.w / 2, k.y + k.h / 2 + 1 + (k.press ? 2 : 0), { size: k.ch === '>' ? 13 : 20, font: k.ch === '<' || k.ch === '>' ? 'ui' : 'display', color: '#fafafa' });
        }
        if (toast) { const a = Math.min(1, toast.t * 3); g.globalAlpha = a; D.fillRR(g, W / 2 - 140, 574, 280, 52, 10, '#fafafa'); D.text(g, toast.msg, W / 2, 601, { size: 20, font: 'ui', weight: 700, color: '#18181b' }); g.globalAlpha = 1; }
      },
    };
  },
});
